import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:5179/', { waitUntil: 'networkidle' });
const snap = async (label) => {
  const data = await page.evaluate(() => ({
    lang: document.documentElement.lang,
    title: document.title,
    body: document.body.innerText,
    stored: localStorage.getItem('app-language'),
  }));
  console.log(`--- ${label}`, JSON.stringify({ lang: data.lang, title: data.title, stored: data.stored }));
  console.log(data.body.split('\n').filter(Boolean).join(' | '));
};
await snap('initial');
await page.getByRole('radio', { name: 'Русский' }).click({ force: true }).catch(async () => page.getByText('Русский').click());
await page.getByRole('button', { name: 'Увеличить' }).click();
await page.getByRole('button', { name: 'Увеличить' }).click();
await page.getByRole('button', { name: 'Увеличить' }).click();
await page.getByRole('button', { name: 'Увеличить' }).click();
await page.getByRole('button', { name: 'Увеличить' }).click();
await snap('ru after 5 clicks');
await page.reload({ waitUntil: 'networkidle' });
await snap('ru after reload (persisted, count reset)');
await page.getByText('English').click();
await snap('en after switching back');
await page.screenshot({ path: '/tmp/i18n-check/en.png' });
await page.getByText('Русский').click();
await page.screenshot({ path: '/tmp/i18n-check/ru.png' });
console.log('errors:', errors);
await browser.close();
EOF
