// @vitest-environment jsdom
import { act, fireEvent, render, screen, cleanup } from '@testing-library/react';
import { afterEach, describe, expect, it } from 'vitest';
import { App } from './App';

afterEach(() => { cleanup(); localStorage.clear(); });

describe('language switch', () => {
  it('switches UI, plurals, html lang, title and gravity strings; persists across mounts', async () => {
    const { unmount } = render(<App />);
    expect(screen.getByText('Hello, world!')).toBeTruthy();
    expect(document.documentElement.lang).toBe('en');

    await act(async () => { fireEvent.click(screen.getByText('Русский')); });
    expect(screen.getByText('Привет, мир!')).toBeTruthy();
    expect(document.documentElement.lang).toBe('ru');
    expect(document.title).toBe('Gravity UI eval');
    expect(localStorage.getItem('app-language')).toBe('ru');
    expect(screen.getByText('0 кликов')).toBeTruthy();
    expect(screen.getByRole('radiogroup', { name: 'Язык интерфейса' })).toBeTruthy();

    for (let i = 0; i < 2; i++) await act(async () => { fireEvent.click(screen.getByText('Увеличить')); });
    expect(screen.getByText('2 клика')).toBeTruthy();

    await act(async () => { fireEvent.click(screen.getByText('English')); });
    expect(screen.getByText('Hello, world!')).toBeTruthy();
    expect(screen.getByText('2 clicks')).toBeTruthy();
    expect(document.documentElement.lang).toBe('en');
    expect(localStorage.getItem('app-language')).toBe('en');

    unmount();
    await act(async () => { fireEvent.click(screen.getByText('English')) }).catch(() => {});
  });

  it('restores stored language on mount and ignores invalid stored values', async () => {
    localStorage.setItem('app-language', 'ru');
    const first = render(<App />);
    expect(screen.getByText('Привет, мир!')).toBeTruthy();
    first.unmount();
    localStorage.setItem('app-language', 'de');
    render(<App />);
    expect(screen.getByText('Hello, world!')).toBeTruthy();
  });
});
EOF
